-- Choice-question focused expansion for MVP practice volume.

INSERT INTO questions (
    id, subject_id, chapter_id, type, difficulty, stem, answer, explanation,
    source, source_year, score, status, review_status, review_note,
    stem_format, stem_image_url, reviewed_at, created_at, updated_at
)
SELECT
    CAST(q.id AS UUID),
    s.id,
    c.id,
    'SINGLE_CHOICE',
    q.difficulty,
    q.stem,
    q.answer,
    q.explanation,
    q.source,
    q.source_year,
    2.00,
    'PUBLISHED',
    'APPROVED',
    '选择题专项扩容：先保障题量和可练习性。',
    'PLAIN_TEXT',
    NULL,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000019001','DATA_STRUCTURE','DS_LINEAR_LIST','ORIGINAL',NULL,'BASIC','顺序表最适合下列哪类操作频繁的场景？','A','顺序表支持按下标 O(1) 随机访问，因此适合随机访问频繁而插入删除较少的场景。','按下标随机访问','在表头频繁插入','在任意位置频繁删除','存储规模完全未知'),
    ('00000000-0000-0000-0000-000000019002','DATA_STRUCTURE','DS_LINEAR_LIST','MOCK',2026,'MEDIUM','在长度为 n 的单链表中查找第 i 个结点，平均时间复杂度为？','C','单链表不能按下标直接定位，需要从头指针沿 next 逐个访问，平均和最坏时间复杂度均为 O(n)。','O(1)','O(log n)','O(n)','O(n log n)'),
    ('00000000-0000-0000-0000-000000019003','DATA_STRUCTURE','DS_STACK_QUEUE','PAST_EXAM',2023,'BASIC','队列的基本操作特性是？','B','队列限定一端入队、另一端出队，体现先进先出。','后进先出','先进先出','随机访问','按关键字有序访问'),
    ('00000000-0000-0000-0000-000000019004','DATA_STRUCTURE','DS_STACK_QUEUE','ORIGINAL',NULL,'MEDIUM','表达式求值中，栈常用于处理括号和运算符优先级，主要利用了栈的哪种特性？','D','括号匹配和运算符延迟处理都需要最近出现的元素最先处理，正好符合后进先出。','先进先出','顺序随机访问','哈希定位','后进先出'),
    ('00000000-0000-0000-0000-000000019005','DATA_STRUCTURE','DS_TREE','MOCK',2026,'MEDIUM','一棵二叉树第 5 层最多有多少个结点？假设根为第 1 层。','C','二叉树第 k 层最多有 2^(k-1) 个结点，因此第 5 层最多 16 个。','8','15','16','32'),
    ('00000000-0000-0000-0000-000000019006','DATA_STRUCTURE','DS_TREE','PAST_EXAM',2023,'HARD','已知一棵二叉树的先序和中序序列，能唯一确定该二叉树的前提是？','A','先序确定根，中序划分左右子树，递归处理即可唯一确定二叉树。','结点关键字互不相同','二叉树必须是满二叉树','二叉树必须是完全二叉树','后序序列也必须已知'),
    ('00000000-0000-0000-0000-000000019007','DATA_STRUCTURE','DS_GRAPH','ORIGINAL',NULL,'BASIC','用邻接表存储稀疏图，相比邻接矩阵通常更节省什么？','B','稀疏图边数远小于顶点数平方，邻接表只保存实际边，空间更省。','CPU 指令数','存储空间','结点关键字长度','图的顶点数'),
    ('00000000-0000-0000-0000-000000019008','DATA_STRUCTURE','DS_GRAPH','MOCK',2026,'MEDIUM','对有向无环图进行拓扑排序，若图中存在环，则结果通常如何？','C','拓扑排序要求不存在有向环，若存在环就无法得到包含全部顶点的拓扑序列。','一定得到唯一序列','一定得到逆序序列','无法完成全部顶点排序','自动转为广度优先遍历'),
    ('00000000-0000-0000-0000-000000019009','DATA_STRUCTURE','DS_SORT','PAST_EXAM',2023,'MEDIUM','下列排序方法中，最坏时间复杂度仍为 O(n log n) 的是？','D','堆排序最坏时间复杂度为 O(n log n)，而快速排序最坏可退化为 O(n^2)。','直接插入排序','冒泡排序','快速排序','堆排序'),
    ('00000000-0000-0000-0000-000000019010','DATA_STRUCTURE','DS_SORT','ORIGINAL',NULL,'BASIC','简单选择排序每一趟通常做什么？','A','简单选择排序每趟从待排序部分选择最小或最大元素，与待排序区首元素交换。','选择最小元素放到有序区末尾','只比较相邻元素并交换','把序列递归二分','按散列地址放置元素'),
    ('00000000-0000-0000-0000-000000019011','DATA_STRUCTURE','DS_TREE','MOCK',2026,'HARD','若二叉排序树按递增序列依次插入关键字，且不做平衡处理，其形态最可能退化为？','B','递增插入会使每个新结点都成为右孩子，二叉排序树退化为单链结构。','完全二叉树','单链表','满二叉树','堆'),
    ('00000000-0000-0000-0000-000000019012','DATA_STRUCTURE','DS_GRAPH','PAST_EXAM',2023,'HARD','Prim 算法通常用于求解下列哪类问题？','C','Prim 算法从一个顶点开始逐步扩展，常用于求连通带权无向图的最小生成树。','单源最短路径','拓扑排序','最小生成树','关键路径'),

    ('00000000-0000-0000-0000-000000019013','COMPUTER_ORGANIZATION','CO_NUMBER','ORIGINAL',NULL,'BASIC','定点整数补码加减运算中，溢出判断主要关注什么？','A','补码加法溢出通常发生在同号数相加结果变号时。','符号位是否异常变化','尾数是否规格化','磁盘是否已满','Cache 是否命中'),
    ('00000000-0000-0000-0000-000000019014','COMPUTER_ORGANIZATION','CO_NUMBER','MOCK',2026,'MEDIUM','8 位补码表示中，十进制 -5 的补码是？','D','+5 为 00000101，按位取反得 11111010，再加 1 得 11111011。','00000101','10000101','11111010','11111011'),
    ('00000000-0000-0000-0000-000000019015','COMPUTER_ORGANIZATION','CO_CACHE','PAST_EXAM',2023,'MEDIUM','Cache 与主存之间的数据交换单位通常是？','B','Cache 与主存按块进行数据调入和替换，块是二者交换的基本单位。','位','块','文件','进程'),
    ('00000000-0000-0000-0000-000000019016','COMPUTER_ORGANIZATION','CO_CACHE','ORIGINAL',NULL,'HARD','组相联 Cache 中，替换算法在哪个范围内选择被替换块？','C','组相联映射中，主存块只能映射到某一组，替换只在该组内部进行。','整个主存','任意 Cache 行','对应组内','所有寄存器'),
    ('00000000-0000-0000-0000-000000019017','COMPUTER_ORGANIZATION','CO_INSTRUCTION','MOCK',2026,'BASIC','操作码字段的主要作用是指出什么？','A','操作码决定指令要执行的操作类型，如加、减、访存、转移等。','指令操作类型','操作数物理地址','Cache 行号','中断向量大小'),
    ('00000000-0000-0000-0000-000000019018','COMPUTER_ORGANIZATION','CO_INSTRUCTION','PAST_EXAM',2023,'MEDIUM','寄存器间接寻址中，寄存器内容通常表示什么？','D','寄存器间接寻址的寄存器中存放操作数所在主存单元的地址。','操作数本身','下一条指令','操作码','操作数地址'),
    ('00000000-0000-0000-0000-000000019019','COMPUTER_ORGANIZATION','CO_CPU','ORIGINAL',NULL,'MEDIUM','控制器的基本功能是？','B','控制器负责取指、译码并发出控制信号，协调数据通路完成指令。','长期保存用户文件','产生控制信号并协调指令执行','只负责网络传输','只进行浮点加法'),
    ('00000000-0000-0000-0000-000000019020','COMPUTER_ORGANIZATION','CO_CPU','MOCK',2026,'HARD','流水线中的结构相关通常由什么引起？','A','结构相关是多条指令在同一时刻争用同一个硬件资源导致的冲突。','硬件资源冲突','分支预测正确','数据已经旁路','主存容量过大'),
    ('00000000-0000-0000-0000-000000019021','COMPUTER_ORGANIZATION','CO_IO','PAST_EXAM',2023,'BASIC','中断方式 I/O 相比程序查询方式的主要优点是？','C','中断方式下 CPU 不必持续轮询设备状态，可在设备就绪时再响应，提高利用率。','一定不需要硬件支持','不能并行工作','减少 CPU 无效等待','取消所有设备驱动'),
    ('00000000-0000-0000-0000-000000019022','COMPUTER_ORGANIZATION','CO_IO','ORIGINAL',NULL,'MEDIUM','DMA 传送结束后，通常通过什么方式通知 CPU？','B','DMA 传送完成后，DMA 控制器通常向 CPU 发出中断请求。','轮询源程序','中断','删除页表','修改 DNS'),
    ('00000000-0000-0000-0000-000000019023','COMPUTER_ORGANIZATION','CO_CACHE','MOCK',2026,'HARD','若 Cache 命中率提高，在其他条件不变时平均访存时间通常如何变化？','A','命中率提高意味着更多访问以较短命中时间完成，平均访存时间通常降低。','降低','升高','必为 0','与访存无关'),
    ('00000000-0000-0000-0000-000000019024','COMPUTER_ORGANIZATION','CO_NUMBER','PAST_EXAM',2023,'HARD','浮点数阶码上溢通常表示什么？','D','阶码超过可表示范围通常表示运算结果绝对值过大，无法按当前格式表示。','结果太接近 0','尾数全为 0','符号位错误','结果绝对值过大'),

    ('00000000-0000-0000-0000-000000019025','OPERATING_SYSTEM','OS_PROCESS','ORIGINAL',NULL,'BASIC','进程与程序的主要区别是？','A','程序是静态代码，进程是程序在某个数据集合上的一次动态执行过程。','进程是动态执行实体','程序一定占用 CPU','程序一定有 PCB','进程不能并发'),
    ('00000000-0000-0000-0000-000000019026','OPERATING_SYSTEM','OS_PROCESS','MOCK',2026,'MEDIUM','时间片轮转调度主要适用于哪类系统目标？','B','时间片轮转强调公平和较快响应，常用于分时系统。','批处理吞吐最大化','分时系统响应','只运行最短作业','只处理实时硬中断'),
    ('00000000-0000-0000-0000-000000019027','OPERATING_SYSTEM','OS_MEMORY','PAST_EXAM',2023,'MEDIUM','请求分页系统发生缺页中断时，操作系统通常首先需要做什么？','C','缺页时需判断访问是否合法，若合法再调入所需页面。','立即结束所有进程','直接修改文件名','判断访问是否合法并调页','清空全部页表'),
    ('00000000-0000-0000-0000-000000019028','OPERATING_SYSTEM','OS_MEMORY','ORIGINAL',NULL,'HARD','LRU 页面置换算法淘汰的是哪类页面？','D','LRU 淘汰最长时间未被访问的页面，利用程序局部性思想。','最先进入内存的页面','编号最大的页面','最小的页面','最长时间未使用的页面'),
    ('00000000-0000-0000-0000-000000019029','OPERATING_SYSTEM','OS_FILE','MOCK',2026,'BASIC','文件控制块 FCB 通常保存什么？','A','FCB 保存文件属性、位置、权限等管理文件所需的元数据。','文件管理所需元数据','CPU 算术结果','网络拥塞窗口','Cache 替换位'),
    ('00000000-0000-0000-0000-000000019030','OPERATING_SYSTEM','OS_FILE','PAST_EXAM',2023,'MEDIUM','索引分配文件的主要优点是？','B','索引分配通过索引块记录文件各块地址，支持文件离散存放并便于随机访问。','必须连续存放','支持离散存放和随机访问','不需要磁盘块','只能顺序访问'),
    ('00000000-0000-0000-0000-000000019031','OPERATING_SYSTEM','OS_DEADLOCK','ORIGINAL',NULL,'MEDIUM','破坏死锁的请求并保持条件，可采用哪种策略？','C','一次性申请全部所需资源或申请新资源前释放已持有资源，可破坏请求并保持。','允许循环等待','资源永不释放','一次申请全部资源','禁止互斥资源'),
    ('00000000-0000-0000-0000-000000019032','OPERATING_SYSTEM','OS_DEADLOCK','MOCK',2026,'HARD','系统处于安全状态意味着什么？','A','安全状态表示存在某种安全序列，使所有进程都能顺利完成，因此不会立即进入死锁。','存在安全序列','所有资源都空闲','所有进程都阻塞','一定没有资源竞争'),
    ('00000000-0000-0000-0000-000000019033','OPERATING_SYSTEM','OS_IO','PAST_EXAM',2023,'BASIC','设备独立性的主要含义是？','D','设备独立性使应用程序使用逻辑设备名，尽量不依赖具体物理设备。','设备不需要驱动','设备不能共享','设备只能顺序访问','程序不依赖具体物理设备'),
    ('00000000-0000-0000-0000-000000019034','OPERATING_SYSTEM','OS_IO','ORIGINAL',NULL,'MEDIUM','双缓冲相比单缓冲通常可以带来什么好处？','B','双缓冲可使设备输入输出和 CPU 处理更好重叠，提高并行度。','减少所有磁盘容量','提高设备与 CPU 并行度','取消中断机制','让文件变为连续分配'),
    ('00000000-0000-0000-0000-000000019035','OPERATING_SYSTEM','OS_MEMORY','MOCK',2026,'HARD','分页系统中页表项的有效位通常用于表示什么？','C','有效位表示该页当前是否已调入内存，可用于缺页判断。','页面是否可写源代码','磁盘是否坏道','页面是否在内存中','进程是否结束'),
    ('00000000-0000-0000-0000-000000019036','OPERATING_SYSTEM','OS_PROCESS','PAST_EXAM',2023,'HARD','PV 操作中，P 操作对信号量的基本影响是？','A','P 操作先将信号量减 1，若结果小于 0，进程通常阻塞等待。','减 1 并可能阻塞','加 1 并唤醒进程','清空就绪队列','直接终止进程'),

    ('00000000-0000-0000-0000-000000019037','COMPUTER_NETWORK','CN_PHYSICAL','ORIGINAL',NULL,'BASIC','奈奎斯特准则讨论的是哪类信道的最大码元传输速率？','B','奈奎斯特准则给出理想低通信道在无噪声条件下的最高码元传输速率。','任意强噪声信道','理想低通信道','只适用于应用层','只适用于光盘存储'),
    ('00000000-0000-0000-0000-000000019038','COMPUTER_NETWORK','CN_PHYSICAL','MOCK',2026,'MEDIUM','信噪比为 30dB 约等于普通比值多少？','C','dB = 10 log10(S/N)，30dB 对应 S/N = 10^3 = 1000。','30','100','1000','3000'),
    ('00000000-0000-0000-0000-000000019039','COMPUTER_NETWORK','CN_DATA_LINK','PAST_EXAM',2023,'MEDIUM','停止-等待协议中，信道利用率较低的主要原因是？','A','发送方每发送一帧都要等待确认，长传播时延下等待时间占比很大。','每次只能发送一帧并等待确认','帧没有校验和','只能用于广播信道','不需要 ACK'),
    ('00000000-0000-0000-0000-000000019040','COMPUTER_NETWORK','CN_DATA_LINK','ORIGINAL',NULL,'HARD','选择重传协议相比回退 N 帧协议的主要特点是？','D','选择重传只重传出错或丢失的帧，而不是从出错帧开始全部重传。','窗口大小只能为 1','不使用序号','必须重传所有已发送帧','只重传出错帧'),
    ('00000000-0000-0000-0000-000000019041','COMPUTER_NETWORK','CN_NETWORK','MOCK',2026,'BASIC','ARP 协议的主要作用是？','A','ARP 用于在同一链路中根据 IP 地址解析对应的 MAC 地址。','由 IP 地址解析 MAC 地址','由域名解析 IP 地址','压缩 HTTP 报文','进行拥塞控制'),
    ('00000000-0000-0000-0000-000000019042','COMPUTER_NETWORK','CN_NETWORK','PAST_EXAM',2023,'MEDIUM','IPv4 首部中的 TTL 字段主要用于什么？','B','TTL 每经过一个路由器通常减 1，为 0 时丢弃，防止分组无限循环。','表示端口号','防止分组无限循环','表示应用层协议名','记录 MAC 地址'),
    ('00000000-0000-0000-0000-000000019043','COMPUTER_NETWORK','CN_TRANSPORT','ORIGINAL',NULL,'MEDIUM','TCP 三次握手的主要目的不包括下列哪项？','C','三次握手用于确认双方收发能力、同步初始序号和建立连接，不负责域名解析。','同步初始序号','确认双方收发能力','解析域名','建立可靠连接'),
    ('00000000-0000-0000-0000-000000019044','COMPUTER_NETWORK','CN_TRANSPORT','MOCK',2026,'HARD','TCP 快重传通常由什么触发？','A','发送方收到多个重复 ACK 时可推断某报文段丢失，从而不等超时就快速重传。','收到多个重复 ACK','应用层关闭文件','DNS 解析失败','物理层编码改变'),
    ('00000000-0000-0000-0000-000000019045','COMPUTER_NETWORK','CN_APPLICATION','PAST_EXAM',2023,'BASIC','HTTP 是一种什么类型的协议？','D','HTTP 工作在应用层，采用请求-响应模型传输超文本相关资源。','物理层编码协议','网络层路由协议','链路层介质访问协议','应用层请求响应协议'),
    ('00000000-0000-0000-0000-000000019046','COMPUTER_NETWORK','CN_APPLICATION','ORIGINAL',NULL,'MEDIUM','DNS 采用层次化命名空间的主要好处是？','B','层次化命名便于分布式管理和授权，提高扩展性。','保证所有查询都不耗时','便于分布式管理','取消根域名服务器','使 TCP 不再需要连接'),
    ('00000000-0000-0000-0000-000000019047','COMPUTER_NETWORK','CN_NETWORK','MOCK',2026,'HARD','CIDR 聚合路由的主要目的是什么？','C','CIDR 可把多个连续网络前缀聚合为更短前缀，减少路由表规模。','增加每个分组长度','禁止子网划分','减少路由表项','替代传输层端口'),
    ('00000000-0000-0000-0000-000000019048','COMPUTER_NETWORK','CN_DATA_LINK','PAST_EXAM',2023,'HARD','HDLC 帧中采用比特填充的主要目的是什么？','A','比特填充避免数据字段中出现与标志字段相同的比特模式，从而保证帧边界识别。','避免数据中误出现帧定界标志','压缩所有 IP 地址','提高 CPU 主频','替代 CRC 校验')
) AS q(id, subject_code, chapter_code, source, source_year, difficulty, stem, answer, explanation, option_a, option_b, option_c, option_d)
JOIN subjects s ON s.code = q.subject_code
JOIN chapters c ON c.code = q.chapter_code;

INSERT INTO question_options (id, question_id, label, content, sort_order)
SELECT CAST(o.id AS UUID), CAST(o.question_id AS UUID), o.label, o.content, o.sort_order
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000019101','00000000-0000-0000-0000-000000019001','A','按下标随机访问',1),('00000000-0000-0000-0000-000000019102','00000000-0000-0000-0000-000000019001','B','在表头频繁插入',2),('00000000-0000-0000-0000-000000019103','00000000-0000-0000-0000-000000019001','C','在任意位置频繁删除',3),('00000000-0000-0000-0000-000000019104','00000000-0000-0000-0000-000000019001','D','存储规模完全未知',4),
    ('00000000-0000-0000-0000-000000019105','00000000-0000-0000-0000-000000019002','A','O(1)',1),('00000000-0000-0000-0000-000000019106','00000000-0000-0000-0000-000000019002','B','O(log n)',2),('00000000-0000-0000-0000-000000019107','00000000-0000-0000-0000-000000019002','C','O(n)',3),('00000000-0000-0000-0000-000000019108','00000000-0000-0000-0000-000000019002','D','O(n log n)',4),
    ('00000000-0000-0000-0000-000000019109','00000000-0000-0000-0000-000000019003','A','后进先出',1),('00000000-0000-0000-0000-000000019110','00000000-0000-0000-0000-000000019003','B','先进先出',2),('00000000-0000-0000-0000-000000019111','00000000-0000-0000-0000-000000019003','C','随机访问',3),('00000000-0000-0000-0000-000000019112','00000000-0000-0000-0000-000000019003','D','按关键字有序访问',4),
