INSERT INTO question_tags (id, name, created_at)
SELECT CAST(tag.id AS UUID), tag.name, CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000019701','选择题扩容'),
    ('00000000-0000-0000-0000-000000019702','第三批上线题')
) AS tag(id, name)
WHERE NOT EXISTS (SELECT 1 FROM question_tags existing WHERE existing.name = tag.name);

INSERT INTO question_tag_relations (question_id, tag_id)
SELECT CAST(q.id AS UUID), tag.id
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000019001'),('00000000-0000-0000-0000-000000019002'),('00000000-0000-0000-0000-000000019003'),('00000000-0000-0000-0000-000000019004'),('00000000-0000-0000-0000-000000019005'),('00000000-0000-0000-0000-000000019006'),('00000000-0000-0000-0000-000000019007'),('00000000-0000-0000-0000-000000019008'),('00000000-0000-0000-0000-000000019009'),('00000000-0000-0000-0000-000000019010'),('00000000-0000-0000-0000-000000019011'),('00000000-0000-0000-0000-000000019012'),
