    ('00000000-0000-0000-0000-000000019037'),('00000000-0000-0000-0000-000000019038'),('00000000-0000-0000-0000-000000019039'),('00000000-0000-0000-0000-000000019040'),('00000000-0000-0000-0000-000000019041'),('00000000-0000-0000-0000-000000019042'),('00000000-0000-0000-0000-000000019043'),('00000000-0000-0000-0000-000000019044'),('00000000-0000-0000-0000-000000019045'),('00000000-0000-0000-0000-000000019046'),('00000000-0000-0000-0000-000000019047'),('00000000-0000-0000-0000-000000019048')
) AS q(id)
